entries[74269] = { ["name"] = "Blazing Hippogryph", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 20\nRequires Apprentice Riding\nUse: Teaches you how to summon this mount. This is a flying mount." }
entries[74274] = { ["name"] = "Plans: Phantom Blade", ["text"] = "Binds when picked up\nRequires Blacksmithing (270)\nUse: Teaches you how to forge a Phantom Blade.\n\nPhantom Blade\nBinds when equipped\nOne-Hand Sword\n59 - 111 Damage Speed 2.60\n(32.69 damage per second)\nDurability 90 / 90\nRequires Level 44\nChance on hit: Decrease the armor of the target by 100 for 20 sec. While affected, the target cannot stealth or turn invisible.\nSell Price:\nRequires Mithril Bar (28), Breath of Wind (6), Truesilver Bar (8), Lesser Invisibility Potion (2), Aquamarine (6), Solid Grinding Stone (4), Thick Leather (2)" }
entries[74278] = { ["name"] = "Helm of the Fire Festival", ["text"] = "Binds when picked up\nUnique\nHead\n+ 2 Bonus Armor\nUse: Kneel down and allow others to cook over you. (10 Sec Cooldown)" }
