entries[75030] = { ["name"] = "Gnomeregan Gnuggets", ["text"] = "Binds when picked up\nUnique (20)\nUse: Restores 2% of your health per second for 25 sec. Must remain seated while eating.\n\"Breaded, bite-sized, and mechanically inclined. I mean, processed!\"" }
